#include <algorithm>
#include <vector>

bool hasDuplicate(std::vector<int> values)
{
    std::sort(values.begin(), values.end());
    for (std::size_t i = 1; i < values.size(); ++i)
        if (values[i] == values[i - 1]) return true;
    return false;
}

bool hasPairWithSum(const std::vector<int>& sorted, int target)
{
    if (sorted.size() < 2) return false;
    std::size_t lo = 0, hi = sorted.size() - 1;
    while (lo < hi)
    {
        long long sum = static_cast<long long>(sorted[lo]) + sorted[hi];
        if (sum == target) return true;
        if (sum < target) ++lo; else --hi;
    }
    return false;
}

long long maxSubarraySum(const std::vector<int>& values)
{
    if (values.empty()) return 0;
    long long best = values[0], endingHere = values[0];
    for (std::size_t i = 1; i < values.size(); ++i)
    {
        endingHere = std::max<long long>(values[i], endingHere + values[i]);
        best = std::max(best, endingHere);
    }
    return best;
}

std::size_t countBelow(const std::vector<int>& sorted, int limit)
{
    return static_cast<std::size_t>(std::lower_bound(sorted.begin(), sorted.end(), limit) - sorted.begin());
}

