static std::vector<int> big(int n, int step) { std::vector<int> v(n); for (int i = 0; i < n; ++i) v[i] = i * step; return v; }

TEST("duplicates") {
    CHECK(hasDuplicate({ 3, 1, 4, 1, 5 }));
    CHECK(!hasDuplicate({ 3, 1, 4, 2, 5 }));
    CHECK(!hasDuplicate({}));
    CHECK(!hasDuplicate({ 7 }));
}
TEST("duplicates in 100,000 values") {
    std::vector<int> v = big(100000, 3);
    CHECK(!hasDuplicate(v));
    v[70000] = v[123];
    CHECK(hasDuplicate(v));
}
TEST("pairs with a sum") {
    CHECK(hasPairWithSum({ 1, 2, 4, 7, 11 }, 9));
    CHECK(hasPairWithSum({ 1, 2, 4, 7, 11 }, 18));
    CHECK(!hasPairWithSum({ 1, 2, 4, 7, 11 }, 10));
    CHECK(!hasPairWithSum({ 5 }, 10));
    CHECK(hasPairWithSum({ 5, 5 }, 10));
    CHECK(!hasPairWithSum({}, 0));
    CHECK(hasPairWithSum({ -8, -3, 0, 6 }, -11));
}
TEST("pairs in 100,000 values") {
    std::vector<int> v = big(100000, 2);
    CHECK(!hasPairWithSum(v, 7));
    CHECK(hasPairWithSum(v, 199994));
    CHECK(!hasPairWithSum(v, 2000000));
}
TEST("maximum subarray") {
    CHECK_EQ(maxSubarraySum({ -2, 1, -3, 4, -1, 2, 1, -5, 4 }), 6LL);
    CHECK_EQ(maxSubarraySum({ -3, -1, -2 }), -1LL);
    CHECK_EQ(maxSubarraySum({ 5 }), 5LL);
    CHECK_EQ(maxSubarraySum({}), 0LL);
    CHECK_EQ(maxSubarraySum({ 2000000000, 2000000000 }), 4000000000LL);
}
TEST("maximum subarray of 100,000 values") {
    std::vector<int> v(100000);
    for (int i = 0; i < 100000; ++i) v[i] = (i % 3 == 0) ? -5 : 3;
    CHECK_EQ(maxSubarraySum(v), 33338LL);      // 33332 blocks of 3, 3, -5, then a final 3, 3
}
TEST("counting below a limit") {
    std::vector<int> v{ 1, 3, 3, 5, 8 };
    CHECK_EQ(countBelow(v, 3), std::size_t{ 1 });
    CHECK_EQ(countBelow(v, 4), std::size_t{ 3 });
    CHECK_EQ(countBelow(v, 0), std::size_t{ 0 });
    CHECK_EQ(countBelow(v, 100), std::size_t{ 5 });
    std::vector<int> b = big(100000, 1);
    long long total = 0;
    for (int i = 0; i < 100000; ++i) total += static_cast<long long>(countBelow(b, i));
    CHECK_EQ(total, 4999950000LL);
}

